import{_ as t,o as a,c as o,a0 as n}from"./chunks/framework.C3yZ6M33.js";const g=JSON.parse('{"title":"Threat model: who trusts whom, and what happens when trust is wrong","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/threat-model.md","filePath":"explanation/threat-model.md"}'),r={name:"explanation/threat-model.md"};function s(i,e,d,c,h,l){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="threat-model-who-trusts-whom-and-what-happens-when-trust-is-wrong" tabindex="-1">Threat model: who trusts whom, and what happens when trust is wrong <a class="header-anchor" href="#threat-model-who-trusts-whom-and-what-happens-when-trust-is-wrong" aria-label="Permalink to &quot;Threat model: who trusts whom, and what happens when trust is wrong&quot;">​</a></h1><p>This document complements <a href="./safety.html">Safety</a>, which covers <em>how</em> capability enforcement works. This document covers <em>who</em> is trusted, <em>what</em> each role must guarantee, <em>what happens when a role is wrong</em>, and <em>what is confined vs. not confined</em>. If you are building a production deployment on peregrin, read this before trusting the safety claims.</p><h2 id="the-roles" tabindex="-1">The roles <a class="header-anchor" href="#the-roles" aria-label="Permalink to &quot;The roles&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Role</th><th>Who/what</th><th>Trust level</th><th>What it controls</th></tr></thead><tbody><tr><td><strong>Campaign author</strong></td><td>Human who writes the campaign YAML and its <code>capabilities:</code></td><td>Trusted</td><td>The capability boundary (the &quot;constitution&quot;)</td></tr><tr><td><strong>Operator</strong></td><td>Human who runs <code>install</code>/<code>create</code>/<code>deploy</code> and feeds the secrets record</td><td>Trusted</td><td>Which bundles exist, which repos are watched, the secret <em>values</em></td></tr><tr><td><strong>Generator</strong></td><td>AI that creates new node specs</td><td>Untrusted</td><td>Node specs (data)</td></tr><tr><td><strong>Reviewer</strong></td><td>AI that reduces the generator&#39;s capabilities before injection</td><td>Semi-trusted</td><td>Which self-attested caps survive</td></tr><tr><td><strong>Engine</strong></td><td><code>Runner::execute_node</code> — the dispatch-time check</td><td>Trusted (mechanical)</td><td>Whether a node&#39;s resolved <code>params:</code> may run</td></tr><tr><td><strong>Driver</strong></td><td>shell, http, agent, git, … — executes the node</td><td>Untrusted (runs after check)</td><td>Side effects within the granted capability surface</td></tr><tr><td><strong>Ingress</strong></td><td><code>github-webhook</code>, <code>sturn-poll</code> — pushes events into a live run</td><td>Untrusted input, trusted plumbing</td><td>Which external events enter the graph</td></tr><tr><td><strong>Agent runtime</strong></td><td>The agent inside a <code>driver: agent</code> node</td><td>Untrusted</td><td>Behaviour within its own sandbox/permission mode</td></tr></tbody></table><h2 id="trust-boundary-the-campaign-caps-are-the-line" tabindex="-1">Trust boundary: the campaign caps are the line <a class="header-anchor" href="#trust-boundary-the-campaign-caps-are-the-line" aria-label="Permalink to &quot;Trust boundary: the campaign caps are the line&quot;">​</a></h2><p>The <strong>campaign-level <code>capabilities:</code> block</strong> is the trust boundary. It is declared by the (trusted) author and cannot be widened by any AI role. Here is why that matters:</p><h3 id="the-self-attestation-problem" tabindex="-1">The self-attestation problem <a class="header-anchor" href="#the-self-attestation-problem" aria-label="Permalink to &quot;The self-attestation problem&quot;">​</a></h3><p>Node-level capabilities with <code>merge: false</code> (the default) <strong>replace</strong> the campaign&#39;s caps. So a generator can self-attest <code>shell.allow: [&quot;*&quot;]</code> and, if left unchecked, that node would bypass the campaign&#39;s narrower <code>shell.allow: [&quot;echo *&quot;]</code>. This is not a bug — it is the mechanism that lets a node declare &quot;I only need eslint, not the full git/npm baseline.&quot; But it means <strong>self-attested caps are not confinement; they are a request.</strong></p><h3 id="what-the-reviewer-must-guarantee" tabindex="-1">What the reviewer must guarantee <a class="header-anchor" href="#what-the-reviewer-must-guarantee" aria-label="Permalink to &quot;What the reviewer must guarantee&quot;">​</a></h3><p>The reviewer&#39;s job is <strong>capability reduction</strong>: strip the generator&#39;s self-attested <code>capabilities</code> key so the node falls back to the campaign&#39;s boundary, or replace it with a <em>narrower</em> grant. The reviewer must:</p><ol><li><strong>Remove or narrow</strong> every self-attested capability that exceeds the campaign boundary.</li><li><strong>Not introduce</strong> capabilities the campaign does not grant.</li></ol><p>The reviewer does <strong>not</strong> need to be perfect. It needs to be conservative: when in doubt, strip. Stripping too much makes a node fail safely.</p><h3 id="what-happens-when-the-reviewer-is-wrong" tabindex="-1">What happens when the reviewer is wrong <a class="header-anchor" href="#what-happens-when-the-reviewer-is-wrong" aria-label="Permalink to &quot;What happens when the reviewer is wrong&quot;">​</a></h3><p><strong>Reviewer is too strict (strips too much):</strong> the node is blocked by the caps, emits <code>capability.violation</code>, and does not run. <strong>Blast radius: the node does not execute. No side effects. This is the safe failure mode.</strong></p><p><strong>Reviewer is too permissive (leaves a dangerous cap in place):</strong> if the reviewer leaves <code>shell.allow: [&quot;*&quot;]</code> on a node with <code>params.cmd: &quot;rm -rf /&quot;</code>, and <code>merge: false</code> replaces the campaign caps, the node&#39;s caps now allow <code>rm</code>. <strong>Blast radius: the node executes with the self-attested caps. The campaign boundary is bypassed for that node.</strong></p><h2 id="open-gap-inject-narrowing" tabindex="-1">Open gap: inject narrowing <a class="header-anchor" href="#open-gap-inject-narrowing" aria-label="Permalink to &quot;Open gap: inject narrowing&quot;">​</a></h2><p>The single most important unfinished safety item, inherited from v1: <strong><code>ctx.inject</code> does not refuse to inject a node whose capabilities exceed the injecting node&#39;s.</strong> <code>LocalBus::inject</code> registers specs as-is. The dispatch-time capability check still runs on the injected node — the <em>campaign</em> boundary holds — but if the reviewer left broad self-attested caps in place, the injected node can carry wider caps than the injector&#39;s own. Until narrowing ships, the safe pattern is to <strong>strip caps, not narrow</strong>.</p><h2 id="what-is-confined-vs-not-confined" tabindex="-1">What is confined vs. not confined <a class="header-anchor" href="#what-is-confined-vs-not-confined" aria-label="Permalink to &quot;What is confined vs. not confined&quot;">​</a></h2><h3 id="confined-the-engine-guarantees-this" tabindex="-1">Confined (the engine guarantees this) <a class="header-anchor" href="#confined-the-engine-guarantees-this" aria-label="Permalink to &quot;Confined (the engine guarantees this)&quot;">​</a></h3><ul><li><strong>Which shell commands run</strong> — <code>params.cmd</code> is checked before the shell starts (deny-then-allow globs).</li><li><strong>Which URLs are fetched</strong> — <code>params.url</code> is checked before the HTTP request.</li><li><strong>Which agent runners are invoked</strong> — <code>params.runner</code> against <code>agents</code> (exact match).</li><li><strong>Which template effects fire</strong> — <code>${env()}</code>/<code>${file()}</code>/ <code>${shell()}</code> calls need a <code>capabilities.&lt;name&gt;</code> grant; strict mode glob-matches the argument.</li><li><strong>Which secrets are visible</strong> — <code>capabilities.secrets</code> gates <code>${secret.*}</code>, <code>ctx.get_secret</code>, and every <code>*_env</code> driver param; the name itself is glob-matched under strict.</li><li><strong>Which events enter a run</strong> — ingress drivers verify before they inject: <code>github-webhook</code> demands a per-repo HMAC signature and a watched-repo allowlist; unknown repos and bad signatures are rejected upstream of the graph.</li><li><strong>Where webhooks bind</strong> — under <code>default_policy: deny</code>, the <code>webhook</code> capability policy checks <code>ports</code>/<code>hosts</code>/<code>paths</code> and can require auth config.</li></ul><h3 id="not-confined-the-engine-does-not-guarantee-this" tabindex="-1">Not confined (the engine does NOT guarantee this) <a class="header-anchor" href="#not-confined-the-engine-does-not-guarantee-this" aria-label="Permalink to &quot;Not confined (the engine does NOT guarantee this)&quot;">​</a></h3><ul><li><strong>What a shell command does once it starts.</strong> The capability confines the <em>command surface</em>, not the command&#39;s effects — <code>allow: [&quot;make *&quot;]</code> still runs whatever the Makefile does.</li><li><strong>What an agent does within its own sandbox.</strong> The engine confines <em>that</em> the agent runs and its permission mode, not its runtime behaviour.</li><li><strong>OS-level escape.</strong> No seccomp, firejail, or container confinement — run untrusted campaigns in a container or VM.</li><li><strong>The secrets record source.</strong> <code>RunOptions.secrets</code> is fed by the caller; the engine gates <em>reads</em>, but who populates the record is an operator decision. The ops verbs resolve names through env → keyring → <code>~/.config/peregrin/env</code> — the run-side feed of that chain is pending wiring.</li></ul><p><strong>Summary:</strong> the engine confines the <strong>declared interface</strong>. It does not confine the <strong>runtime behaviour</strong> within that interface.</p><h2 id="supply-chain-the-bundle-is-code" tabindex="-1">Supply chain: the bundle is code <a class="header-anchor" href="#supply-chain-the-bundle-is-code" aria-label="Permalink to &quot;Supply chain: the bundle is code&quot;">​</a></h2><p><code>peregrin install &lt;ref&gt;</code> fetches a bundle and <code>create</code> materializes a config that <em>executes</em> it — a bundle is remote code running on your node, with your secrets record. The mitigations are pinning, not sandboxing:</p><ul><li><code>#&lt;ref&gt;</code> pins to a branch/tag/sha; the resolved commit sha is always recorded, and <code>#sha256:</code> tarball refs are content-pinned.</li><li><code>peregrin verify &lt;name&gt;</code> digest-checks installed contents against the recorded sha.</li><li>A bundle can declare <code>capabilities:</code> — treat a bundle&#39;s requested caps the way you treat a mobile app&#39;s permission list. Audit <code>peregrin info &lt;name&gt;</code> before <code>create</code>.</li></ul><h2 id="practical-guidance" tabindex="-1">Practical guidance <a class="header-anchor" href="#practical-guidance" aria-label="Permalink to &quot;Practical guidance&quot;">​</a></h2><p>If you are deploying peregrin campaigns today:</p><ol><li><strong>Set campaign-level <code>default_policy: deny</code> + <code>strict: true</code></strong> and declare only the caps the campaign needs — strict is what turns <code>capability.violation</code> into <code>node.failed</code> and glob-matches secret names.</li><li><strong>Strip, don&#39;t narrow.</strong> Remove the <code>capabilities</code> key from generated/injected nodes.</li><li><strong>Assume the reviewer is fallible.</strong> Design campaigns so a too-permissive review fails <em>safe</em> (harmless or reversible), not <em>unsafe</em>.</li><li><strong>Don&#39;t rely on the engine for OS-level confinement.</strong> Run untrusted campaigns in a container or VM.</li><li><strong>Subscribe to <code>capability.violation</code>.</strong> Log it, alert on it, and treat it as a signal that the reviewer or generator is misbehaving.</li><li><strong>Keep secrets out of the graph.</strong> Params and configs carry secret <em>names</em> (<code>token_env</code>, <code>secret_env</code>, <code>ssh_env</code>); the event log is deliberately shareable — a secret that reaches a payload is a secret in your history file.</li></ol><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./safety.html">Safety</a> — the enforcement mechanics</li><li><a href="./../reference/scope-resolution.html">Scope resolution</a> — the <code>${secret.*}</code> gate contract</li><li><a href="./../reference/distribution.html">Distribution</a> — bundle refs, pins, <code>verify</code></li></ul>',31)])])}const p=t(r,[["render",s]]);export{g as __pageData,p as default};
